import OpenAI from "openai";

const client = new OpenAI({
  apiKey: "your-api-key",
  baseURL: "https://api.subconscious.dev/v1",
});

const response = await client.chat.completions.create({
  model: "subconscious/glm-5.3-marathon",
  messages: [{ role: "user", content: "What is the capital of France?" }],
});

console.log(response.choices[0].message.content);

import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic({
  authToken: "your-api-key",
  baseURL: "https://api.subconscious.dev",
});

const message = await client.messages.create({
  model: "subconscious/glm-5.3-marathon",
  max_tokens: 1024,
  messages: [{ role: "user", content: "What is the capital of France?" }],
});

console.log(message.content[0].text);

const response = await fetch("https://api.subconscious.dev/v1/models", {
  headers: { Authorization: `Bearer ${process.env.SUBCONSCIOUS_API_KEY}` },
});
const catalog = await response.json();
console.log(catalog.data.map((model) => model.id));
console.log(catalog.data.map((model) => model.rate_limits));
